using UnityEditor;using UnityEngine;
public static class StreetLegendDrivingValidator{
 [MenuItem("Street Legend/Validate Driving Test Scene")]
 public static void Validate(){int issues=0;var vehicle=Object.FindObjectOfType<StreetLegendVehicleController>();var trigger=Object.FindObjectOfType<StreetLegendRoadblockTrigger>();var phase=Object.FindObjectOfType<StreetLegendMissionPhase>();var camera=Object.FindObjectOfType<StreetLegendDrivingCamera>();var hud=Object.FindObjectOfType<StreetLegendDrivingHUD>();if(!vehicle){Debug.LogError("Missing vehicle controller.");issues++;}if(vehicle&&!vehicle.GetComponent<Rigidbody>()){Debug.LogError("Vehicle controller requires Rigidbody.");issues++;}if(!trigger){Debug.LogError("Missing roadblock trigger.");issues++;}if(trigger&&!trigger.GetComponent<Collider>()){Debug.LogError("Roadblock trigger missing collider.");issues++;}if(trigger&&trigger.GetComponent<Collider>()&&!trigger.GetComponent<Collider>().isTrigger){Debug.LogError("Roadblock collider is not trigger.");issues++;}if(!phase){Debug.LogError("Missing mission phase controller.");issues++;}else if(!phase.vehicle){Debug.LogError("Mission phase has no vehicle reference.");issues++;}if(!camera||!camera.target){Debug.LogError("Driving camera or camera target missing.");issues++;}if(!hud){Debug.LogError("Driving HUD component missing.");issues++;}if(issues==0)Debug.Log("Driving scene structural validation passed. This does not verify runtime handling, collision or touch behavior.");else Debug.LogWarning("Driving scene structural validation found "+issues+" issue(s).");}
}
